func rtgJvmJvmPackageJvmVariableShift(out *renvoAsm, direction RTGShiftDirection, signed bool) {
	rtgJvmJvmPackageJvmMove(out, rtgJvmScratch, rtgJvmPrimary)
	rtgJvmJvmPackageJvmMove(out, rtgJvmPrimary, rtgJvmTertiary)
	operation := rtgJvmJvmPackageJvmOpShiftRightUnsigned
	if direction == RTGShiftLeft {
		operation = rtgJvmJvmPackageJvmOpShiftLeft
	} else if signed {
		operation = rtgJvmJvmPackageJvmOpShiftRightSigned
	}
	rtgJvmJvmPackageJvmBinary(out, operation, rtgJvmPrimary, rtgJvmScratch)
}
