func rtgJvmJvmPackageJvmCallWordCount(out *renvoAsm, label int, wordCount int) {
	registers := []RTGRegister{
		{Code: 3, Valid: true}, {Code: 4, Valid: true},
		{Code: 1, Valid: true}, {Code: 2, Valid: true},
		{Code: 5, Valid: true}, {Code: 6, Valid: true},
	}
	limit := wordCount
	if limit > len(registers) {
		limit = len(registers)
	}
	for i := 0; i < limit; i++ {
		rtgJvmJvmPackageJvmPopRegister(out, registers[i])
	}
	rtgJvmJvmPackageJvmEmitRegisterImmediate(
		out, rtgJvmJvmPackageJvmOpMoveImmediate, 7, 0)
	at := len(out.code) - 4
	renvoAsmAddReloc(out, at, renvoRTGLabelCode(label))
	rtgJvmJvmPackageJvmCallIndirectWordCount(out, rtgJvmScratch, wordCount)
}
func rtgJvmJvmPackageJvmHostedEntry(out *renvoAsm, parameterCount int, stateOffset int) bool {
	_ = stateOffset
	if parameterCount < 0 || parameterCount > 2 {
		return false
	}
	if parameterCount > 0 {
		argsOffset := out.ReserveBSS(rtgJvmJvmPackageJvmHostArgsBytes, 16)
		renvoAsmEmit8(out, rtgJvmJvmPackageJvmOpBuildArgsEnv)
		at := len(out.code)
		renvoAsmEmit32(out, argsOffset)
		renvoAsmAddAbsReloc(out, at, argsOffset, 1)
		renvoAsmEmit8(out, parameterCount)
	}
	return true
}
