func renvoEmitCompareJumpOp(a *renvoAsm, c0 byte, c1 byte, label int, jumpIfTrue bool, unsigned bool) {
renvoNonNil(a)
	setcc := 0x94
	if c0 == '=' {
		setcc = 0x94
	} else if c0 == '!' {
		setcc = 0x95
	} else if c0 == '<' {
		if c1 == '=' {
			setcc = 0x9e
		} else {
			setcc = 0x9c
		}
	} else if c1 == '=' {
		setcc = 0x9d
	} else {
		setcc = 0x9f
	}
	if !jumpIfTrue {
		setcc = setcc ^ 1
	}
	if unsigned && c0 != '=' && c0 != '!' {
		setcc = 0x92
		if c0 == '>' {
			setcc = 0x97
		}
		if c1 == '=' {
			setcc = setcc ^ 4
		}
		if !jumpIfTrue {
			setcc = setcc ^ 1
		}
	}
	renvoRTGDirectJumpCondition(a, renvoRTGConditionFromSetcc(setcc), label)
	return
}

